step_4.solutionCode:
import numpy as np


def scaled_head(a, k, factor):
    head = a[:k].copy()
    head *= factor
    return head


def totals_match(parts, total):
    return bool(np.isclose(np.sum(parts), total))


prices = np.array([10, 20, 30])
print(scaled_head(prices, 2, 2), prices)
print(totals_match([0.1, 0.2], 0.3), 0.1 + 0.2 == 0.3)

